using UnityEngine;
using UnityEngine.UI;
using TMPro;

public sealed class GridShiftDepotAttendant : MonoBehaviour {
 public static bool ModalOpen{get;private set;}public GridShiftActiveOperations operations;public RuntimeAnimatorController idleController;
 [SerializeField]GameObject authoredModel;
 public void AuthorScene(){if(authoredModel!=null)return;var catalog=Resources.Load<GridShiftCitizenCatalog>("GridShiftCitizenCatalog");if(catalog==null||catalog.models.Length==0)return;authoredModel=Instantiate(catalog.models[GridShiftCitizen.StableIndex("factory-reception",catalog.models.Length)],transform,false);authoredModel.name="Depot employee model";foreach(var c in authoredModel.GetComponentsInChildren<Collider>())c.enabled=false;var animator=authoredModel.GetComponentInChildren<Animator>();if(animator!=null){animator.runtimeAnimatorController=idleController!=null?idleController:catalog.controller;animator.applyRootMotion=false;}}
 GridShiftDialogueVisibility conversationView;GameObject window;PlayerMovement player;bool blocked,visible;CursorLockMode cursor;TMP_Text information;Transform head;
 void Start(){if(authoredModel!=null){var animator=authoredModel.GetComponentInChildren<Animator>();head=animator!=null&&animator.isHuman?animator.GetBoneTransform(HumanBodyBones.Head):null;return;}
  var crowd=FindFirstObjectByType<PedestrianManager>();var catalog=Resources.Load<GridShiftCitizenCatalog>("GridShiftCitizenCatalog");if(crowd==null&&catalog!=null){BuildModel(catalog.models,catalog.controller);return;}if(crowd!=null&&crowd.models!=null&&crowd.models.Length>0&&crowd.models[GridShiftCitizen.StableIndex(gameObject.name+transform.position,crowd.models.Length)]!=null){var model=Instantiate(crowd.models[GridShiftCitizen.StableIndex(gameObject.name+transform.position,crowd.models.Length)],transform,false);model.name="Depot employee model";foreach(var c in model.GetComponentsInChildren<Collider>())c.enabled=false;var animator=model.GetComponentInChildren<Animator>();if(animator!=null){animator.runtimeAnimatorController=idleController!=null?idleController:crowd.controller;animator.applyRootMotion=false;head=animator.isHuman?animator.GetBoneTransform(HumanBodyBones.Head):null;}return;}
  var shirt=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=new Color(.95f,.72f,.12f)};
  var skin=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=new Color(.64f,.42f,.28f)};
  Part("Uniform",PrimitiveType.Capsule,new Vector3(0,.9f,0),new Vector3(.42f,.55f,.35f),shirt);
  head=Part("Head",PrimitiveType.Sphere,new Vector3(0,1.55f,0),Vector3.one*.32f,skin);
  foreach(float x in new[]{-.13f,.13f})Part("Leg",PrimitiveType.Cube,new Vector3(x,.32f,0),new Vector3(.17f,.64f,.2f),shirt);
 }
 void BuildModel(GameObject[] models,RuntimeAnimatorController controller){if(models==null||models.Length==0)return;var model=Instantiate(models[GridShiftCitizen.StableIndex("factory-reception",models.Length)],transform,false);foreach(var c in model.GetComponentsInChildren<Collider>())c.enabled=false;var animator=model.GetComponentInChildren<Animator>();if(animator!=null){animator.runtimeAnimatorController=idleController!=null?idleController:controller;animator.applyRootMotion=false;head=animator.isHuman?animator.GetBoneTransform(HumanBodyBones.Head):null;}}
 Transform Part(string name,PrimitiveType type,Vector3 at,Vector3 size,Material material){var go=GameObject.CreatePrimitive(type);go.name=name;go.transform.SetParent(transform,false);go.transform.localPosition=at;go.transform.localScale=size;go.GetComponent<Renderer>().sharedMaterial=material;Destroy(go.GetComponent<Collider>());return go.transform;}
 bool terminalView;
 public void Open(PlayerMovement candidate,bool terminal=false){if(ModalOpen)return;operations=operations!=null?operations:DeliveryManager.Instance.GetComponent<GridShiftActiveOperations>();terminalView=terminal;player=candidate;conversationView=new GridShiftDialogueVisibility(player);blocked=player.ControlsBlocked;cursor=Cursor.lockState;visible=Cursor.visible;player.BlockControls(true);Cursor.lockState=CursorLockMode.None;Cursor.visible=true;ModalOpen=true;GridShiftTutorialGuide.HideForDialogue();if(terminal)GridShiftTutorial.Record("terminal");
  window=new GameObject("Factory service",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));var canvas=window.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=90;var scaler=window.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);scaler.matchWidthOrHeight=.5f;
  var panel=GridShiftUI.Rect("Atendimento",window.transform,new Vector2(650,650));GridShiftDialogueStyle.Surface(panel.gameObject.AddComponent<Image>());GridShiftUI.Stack(panel,28,14);GridShiftDialogueStyle.BrandRow(panel);GridShiftUI.Text(panel,terminal?"FACTORY · PEDIDOS":GridShiftCitizen.NameFor("factory-reception")+" · Recepção",26,40);information=GridShiftUI.Text(panel,"",20,200);
  GridShiftUI.Button(panel,DeliveryManager.Instance.PersonalOrder==null?"Aceitar primeira entrega / novo pedido":"Continuar encomenda atual",()=>{Close();if(DeliveryManager.Instance.PersonalOrder==null)operations.Execute(candidate,"accept",null,out _);},45);GridShiftUI.Button(panel,"Como preparar esta encomenda",Prepare,45);GridShiftUI.Button(panel,"Encerrar conversa",Close,45);Describe();if(!terminal&&!GridShiftTutorial.Greeted)information.text="Bem-vindo ao centro de distribuição da GridShift!\nAqui recebemos, conferimos e preparamos as encomendas.\nVou orientar sua primeira entrega.\nEncerre a conversa e siga o marcador do terminal.";
 }
 System.Collections.IEnumerator OpenDeliveries(PlayerMovement candidate){var tablet=candidate.GetComponent<PortableTablet>();if(tablet!=null&&tablet.Open()){while(tablet.Animating)yield return null;tablet.Operations.Show("Entregas");}}
 void Prepare(){Describe();var o=DeliveryManager.Instance.PersonalOrder;if(o==null)return;information.text+="\nPróxima ação: "+(!o.depotPicked?"pegar a caixa correta no estoque":!o.depotScanned?"levar a caixa ao leitor de conferência":!o.depotPacked?"usar a mesa de embalagem":!o.depotReleased?"etiquetar, separar e liberar na expedição":"sair e carregar a van")+".";}
 void Describe(){var manager=DeliveryManager.Instance;var o=manager.PersonalOrder;information.text=o==null?"Nenhuma encomenda pessoal ativa.\nAceite um pedido para iniciar. A primeira entrega usa uma caixa pequena e um destinatário próximo.":"PEDIDO #"+o.id.Substring(0,8)+" · "+o.weightKg+" kg\n"+manager.Point(o.destinationId)?.displayName+"\n["+(o.depotPicked?"OK":"  ")+"] Caixa coletada   ["+(o.depotScanned?"OK":"  ")+"] Conferência\n["+(o.depotPacked?"OK":"  ")+"] Embalagem   ["+(o.depotReleased?"OK":"  ")+"] Expedição\nSetor "+(o.weightKg<=5?"A":"B")+" · "+o.status+"\nPrazo restante: "+Mathf.Max(0,o.deadlineSeconds-o.elapsedSeconds).ToString("0")+" s";}
 void Update(){if(window!=null&&GridShiftControls.Back){Close();GridShiftControls.SuppressFrame();}}
 void LateUpdate(){if(head!=null&&player!=null&&window!=null){var direction=player.CameraTransform.position-head.position;if(direction.sqrMagnitude>.01f)head.rotation=Quaternion.Slerp(head.rotation,Quaternion.LookRotation(direction),Time.deltaTime*4);}}
 public void Close(){conversationView?.Restore();conversationView=null;if(window!=null){Destroy(window);if(!terminalView)GridShiftTutorial.Record("attendant");}if(player!=null)player.BlockControls(blocked);Cursor.lockState=cursor;Cursor.visible=visible;ModalOpen=false;window=null;}
 void OnDestroy(){if(window!=null)Close();}
}

